/*
 * Wonty landing site: language, the invite page and the buttons. Plain script, no build step,
 * no requests to other hosts, no cookies, no storage.
 *
 *   index.html   data-page="home"    what Wonty is + "Get Wonty"
 *   404.html     data-page="invite"  GitHub Pages serves it for every unknown path, so it is the
 *                                    page of <base>/e/<token> and <base>/c/<token> (and of the
 *                                    fragment form <base>/e/#<token>); anything else: "Page not found"
 *   privacy/, support/  data-page="doc"  generated by scripts/build-legal-pages.mjs from legal/ in
 *                                    20 languages (privacy/ is English, privacy/<code>/ the others);
 *                                    fully static, footer included: this script leaves their text,
 *                                    lang and title alone
 *
 * The invite page cannot show the event or the catalog: the preview functions need a signed-in
 * account (no anonymous access, on purpose). It offers "Open in Wonty" (custom scheme) and
 * "Get Wonty", which copies the invitation link (so the app can offer it after the install, see
 * src/social/clipboard-handoff.ts) and then opens the App Store / TestFlight.
 *
 * The functions are also exposed as window.WontySite for the tests
 * (src/social/__tests__/links-site.test.ts), which keep this parser in step with the app's.
 */
(function (root) {
  'use strict';

  var TOKEN = /^[A-Za-z0-9_-]{16,128}$/;
  var SEGMENTS = { e: 'event', c: 'catalog' };
  /**
   * A base path we are willing to reuse in URLs: '' or `/segment/segment`, never an empty segment
   * (`//host` would be another host), no quotes, no markup.
   */
  var SAFE_BASE = /^(\/[A-Za-z0-9_.~%-]+)*$/;
  var DEFAULT_BASE_URL = 'https://wonty-app.github.io';
  var DEFAULT_HOST = 'wonty-app.github.io';

  function has(object, key) {
    return Object.prototype.hasOwnProperty.call(object, key);
  }

  /**
   * The invite in a page address: `<base>/e/<token>`, `<base>/c/<token>` (a trailing slash is
   * fine) or the fragment form `<base>/e/#<token>`. Returns { kind, segment, token, basePath } or
   * null. `basePath` is what comes before `/e/` ('' at the root of wonty-app.github.io, '/wonty'
   * under a project path); a path with an empty segment (`//host/e/<token>`) is no invite.
   */
  function parseInvitePath(pathname, hash) {
    var parts = String(pathname || '').split('/');
    while (parts.length > 1 && parts[parts.length - 1] === '') parts.pop();
    var last = parts[parts.length - 1];
    var previous = parts[parts.length - 2];
    var basePath;
    if (parts.length >= 3 && has(SEGMENTS, previous) && TOKEN.test(last)) {
      basePath = parts.slice(0, -2).join('/');
      if (!SAFE_BASE.test(basePath)) return null;
      return { kind: SEGMENTS[previous], segment: previous, token: last, basePath: basePath };
    }
    var fragment = String(hash || '').replace(/^#/, '');
    if (parts.length >= 2 && has(SEGMENTS, last) && TOKEN.test(fragment)) {
      basePath = parts.slice(0, -1).join('/');
      if (!SAFE_BASE.test(basePath)) return null;
      return { kind: SEGMENTS[last], segment: last, token: fragment, basePath: basePath };
    }
    return null;
  }

  /** The visitor's language among the site's: exact tag, then the language alone; else English. */
  function pickLanguage(preferred, available) {
    var lower = available.map(function (code) {
      return code.toLowerCase();
    });
    for (var i = 0; i < preferred.length; i += 1) {
      var tag = String(preferred[i] || '')
        .toLowerCase()
        .replace(/_/g, '-');
      if (!tag) continue;
      var exact = lower.indexOf(tag);
      if (exact >= 0) return available[exact];
      var language = tag.split('-')[0];
      // Norwegian: "no" and "nn" read the bokmål texts.
      if (language === 'no' || language === 'nn') language = 'nb';
      for (var j = 0; j < lower.length; j += 1) {
        if (lower[j].split('-')[0] === language) return available[j];
      }
    }
    return 'en';
  }

  /** `t(key)`: the language's string, else the English one, else the key. */
  function translator(strings, language) {
    var own = strings[language] || {};
    var english = strings.en || {};
    return function (key) {
      if (has(own, key)) return own[key];
      if (has(english, key)) return english[key];
      return key;
    };
  }

  /** The App Store page, else the TestFlight invitation, else null (not available yet). */
  function storeUrl(config) {
    var id = String((config && config.APP_STORE_ID) || '').trim();
    if (/^\d+$/.test(id)) return 'https://apps.apple.com/app/id' + id;
    var beta = String((config && config.TESTFLIGHT_URL) || '').trim();
    return /^https:\/\/testflight\.apple\.com\/join\/[A-Za-z0-9]+$/.test(beta) ? beta : null;
  }

  function hostOf(url) {
    var match = /^https:\/\/([^/?#:@]+)/i.exec(String(url || ''));
    return match ? match[1].toLowerCase() : null;
  }

  /**
   * The https link the app should open: this page's own address when it is on a host the app
   * knows (LINK_BASE_URL's or the default one), else rebuilt on LINK_BASE_URL. Always the path
   * form `<base>/e/<token>`.
   */
  function inviteUrl(invite, location, config) {
    var configured = String((config && config.LINK_BASE_URL) || '').replace(/\/+$/, '');
    var base = hostOf(configured) ? configured : DEFAULT_BASE_URL;
    var path = '/' + invite.segment + '/' + invite.token;
    var host = String(location.hostname || '').toLowerCase();
    if (location.protocol === 'https:' && (host === hostOf(base) || host === DEFAULT_HOST)) {
      return 'https://' + location.host + invite.basePath + path;
    }
    return base + path;
  }

  /** `wonty://e/<token>`: opens the app when it is installed. */
  function appUrl(invite, config) {
    var scheme = String((config && config.SCHEME) || 'wonty');
    return scheme + '://' + invite.segment + '/' + invite.token;
  }

  function platformOf(navigator) {
    var agent = String((navigator && navigator.userAgent) || '');
    if (/iPhone|iPad|iPod/.test(agent)) return 'ios';
    // iPadOS reports itself as a Mac, but with touch.
    if (/Macintosh/.test(agent) && navigator.maxTouchPoints > 1) return 'ios';
    if (/Android/i.test(agent)) return 'android';
    return 'other';
  }

  // ---- Clipboard --------------------------------------------------------------------------------

  function legacyCopy(text) {
    try {
      var area = document.createElement('textarea');
      area.value = text;
      area.setAttribute('readonly', '');
      area.style.position = 'fixed';
      area.style.opacity = '0';
      document.body.appendChild(area);
      area.select();
      area.setSelectionRange(0, text.length);
      var copied = document.execCommand('copy');
      document.body.removeChild(area);
      return copied;
    } catch (error) {
      return false;
    }
  }

  /**
   * Copies the link as a URL and as text (the app checks both without reading them). Must be
   * called inside the click handler: browsers only allow it during a user gesture.
   */
  function copyLink(url) {
    var clipboard = root.navigator && root.navigator.clipboard;
    var writeText = function () {
      if (clipboard && typeof clipboard.writeText === 'function') {
        return clipboard.writeText(url).then(
          function () {
            return true;
          },
          function () {
            return legacyCopy(url);
          },
        );
      }
      return Promise.resolve(legacyCopy(url));
    };
    var Item = root.ClipboardItem;
    if (clipboard && typeof clipboard.write === 'function' && typeof Item === 'function') {
      try {
        var types = { 'text/plain': new Blob([url], { type: 'text/plain' }) };
        if (typeof Item.supports !== 'function' || Item.supports('text/uri-list')) {
          types['text/uri-list'] = new Blob([url], { type: 'text/uri-list' });
        }
        return clipboard.write([new Item(types)]).then(
          function () {
            return true;
          },
          writeText,
        );
      } catch (error) {
        return writeText();
      }
    }
    return writeText();
  }

  // ---- Pages ------------------------------------------------------------------------------------

  function show(id, visible) {
    var element = document.getElementById(id);
    if (element) element.hidden = !visible;
    return element;
  }

  function setText(id, text) {
    var element = document.getElementById(id);
    if (element) element.textContent = text;
    return element;
  }

  function platformHint(platform, t) {
    if (platform === 'android') return t('android');
    if (platform === 'other') return t('desktopHint');
    return null;
  }

  function initHome(context) {
    var link = document.getElementById('get-app');
    var store = storeUrl(context.config);
    if (link) {
      if (store) link.setAttribute('href', store);
      else link.hidden = true;
    }
    show('store-hint', !store);
    var hint = platformHint(context.platform, context.t);
    if (hint && context.platform === 'android') {
      setText('platform-hint', hint);
      show('platform-hint', true);
    }
  }

  function initInvite(context) {
    var invite = parseInvitePath(root.location.pathname, root.location.hash);
    if (!invite) {
      show('not-found', true);
      document.title = context.t('notFoundTitle') + ' — Wonty';
      return;
    }
    show('invite', true);
    var event = invite.kind === 'event';
    setText('invite-title', context.t(event ? 'eventTitle' : 'catalogTitle'));
    setText('invite-body', context.t(event ? 'eventBody' : 'catalogBody'));
    var open = document.getElementById('open-app');
    if (open) open.setAttribute('href', appUrl(invite, context.config));

    var hint = platformHint(context.platform, context.t);
    if (hint) {
      setText('platform-hint', hint);
      show('platform-hint', true);
    }

    var button = document.getElementById('get-app');
    if (!button) return;
    var link = inviteUrl(invite, root.location, context.config);
    var store = storeUrl(context.config);
    button.addEventListener('click', function () {
      button.disabled = true;
      copyLink(link).then(function (copied) {
        var message = store ? context.t('copied') : context.t('notInStore');
        setText('status', copied || !store ? message : '');
        if (!store) {
          button.disabled = false;
          return;
        }
        // A moment to read the line, then the store (the copy is done by now).
        root.setTimeout(function () {
          button.disabled = false;
          root.location.href = store;
        }, 700);
      });
    });
  }

  function init() {
    var config = root.WONTY_CONFIG || {};
    var strings = root.WONTY_I18N || { en: {} };
    var navigator = root.navigator || {};
    var preferred =
      navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language];
    var language = pickLanguage(preferred, Object.keys(strings));
    var t = translator(strings, language);
    var page = document.body.getAttribute('data-page');

    var translated = document.querySelectorAll('[data-i18n]');
    for (var i = 0; i < translated.length; i += 1) {
      translated[i].textContent = t(translated[i].getAttribute('data-i18n'));
    }
    if (page !== 'doc') {
      document.documentElement.lang = language;
      document.title = t('pageTitle');
    }
    // The privacy and support pages exist in every language: privacy/ (English), privacy/<code>/.
    if (language !== 'en') {
      var localized = document.querySelectorAll('a[data-localized]');
      for (var k = 0; k < localized.length; k += 1) {
        localized[k].setAttribute('href', localized[k].getAttribute('href') + language + '/');
      }
    }

    var context = { config: config, t: t, platform: platformOf(navigator), language: language };
    if (page === 'home') initHome(context);
    if (page === 'invite') initInvite(context);
  }

  root.WontySite = {
    parseInvitePath: parseInvitePath,
    pickLanguage: pickLanguage,
    translator: translator,
    storeUrl: storeUrl,
    inviteUrl: inviteUrl,
    appUrl: appUrl,
    platformOf: platformOf,
  };

  if (typeof document !== 'undefined' && document.body && !root.WONTY_SITE_NO_INIT) init();
})(typeof window !== 'undefined' ? window : this);
